def template_letters(resume: str, jd: str, lang: str, company: str = "", role: str = "") -> dict:
    """Fill localised tone templates with details mined from the resume and job description."""
    doc = parse_resume(resume)
    report = analyze(resume, jd)
    d_role, d_company, greeting, d_skills = DEFAULTS[lang]
    role = role or extract_role(jd) or d_role
    company = company or extract_company(jd) or d_company
    skills_list = report["keywords"]["matched"][:3]
    skills = ", ".join(skills_list) if skills_list else d_skills
    bullets = [i["text"] for s in doc["sections"] if s["key"] in ("experience", "projects", "achievements")
               for i in s["items"] if i["type"] == "bullet" and NUMBER_RE.search(i["text"])]
    achievement = ""
    if bullets:
        best = improve_bullet(max(bullets, key=lambda b: len(NUMBER_RE.findall(b))), lang).rstrip(".")
        achievement = ACHIEVEMENT[lang].format(a=best[:1].lower() + best[1:] if lang == "en" else best)
    values = {"role": role, "company": company, "greeting": greeting, "skills": skills,
              "achievement": achievement, "name": doc.get("name") or ""}
    return {tone: TEMPLATES[lang][tone].format(**values).strip() for tone in TONES}


async def generate_letters(resume: str, jd: str, language: str | None = None, company: str = "",
                           role: str = "") -> dict:
    """Generate three tailored cover letters; falls back to templates without a local model."""
    lang = language or detect_language(resume)
    st = await llm.status()
    if st["available"]:
        prompt = f"""Write three tailored cover letters in {LANGUAGE_NAMES[lang]} for the candidate below.
Target role: {role or 'infer from the job description'}. Company: {company or 'infer from the job description'}.
Each letter: 200-300 words, greeting, 3 short paragraphs, sign-off with the candidate's name, plain text.
Use only facts found in the resume. Tones:
- "formal": polished and professional
- "conversational": warm, natural and approachable
- "enthusiastic": energetic and passionate, but still professional
Return JSON exactly like {{"formal": "...", "conversational": "...", "enthusiastic": "..."}}.

<job>
{jd[:6000]}
</job>
<resume>
{resume[:10000]}
</resume>"""
        try:
            data = await llm.generate_json(prompt)
            if all(isinstance(data.get(t), str) and len(data[t]) > 80 for t in TONES):
                return {"letters": {t: data[t].strip() for t in TONES}, "engine": "ai", "model": st["model"]}
        except llm.AIUnavailable:
            pass
    return {"letters": template_letters(resume, jd, lang, company, role), "engine": "rules"}
